def entities(doc, scope):
    """
    Return list of {'id': str, 'description': str} for all objects
    defined in the scope.  `id` is used by all other functions.
    """
    scope_node = node_by_title(doc, scope)
    obj_node = None
    for child in children(doc, scope_node):
        if child['kind'] == 'list' and child['title'].startswith(scope + ": Objects"):
            obj_node = child
            break
    if not obj_node:
        return []

    objects, _ = _parse_objects(obj_node['lines'])
    return [{'id': f'obj{oid}', 'description': desc}
            for oid, desc in sorted(objects.items(), key=lambda x: int(x[0]))]


